configuration.jsScript:
var t = msg.temperature != null ? Double.parseDouble(msg.temperature.toString()) : null;
if (t == null) {
    return {msg: msg, metadata: metadata, msgType: msgType};
}

var ll = metadata.ss_alarm_LL != null ? Double.parseDouble(metadata.ss_alarm_LL.toString()) : 5.0;
var l  = metadata.ss_alarm_L  != null ? Double.parseDouble(metadata.ss_alarm_L.toString())  : 12.0;
var h  = metadata.ss_alarm_H  != null ? Double.parseDouble(metadata.ss_alarm_H.toString())  : 38.0;
var hh = metadata.ss_alarm_HH != null ? Double.parseDouble(metadata.ss_alarm_HH.toString()) : 45.0;

msg.alarm_LL = ll;
msg.alarm_L  = l;
msg.alarm_H  = h;
msg.alarm_HH = hh;
msg.currentTemp = Math.round(t * 10.0) / 10.0;

if (t <= ll) {
    msg.alarmCode = "LL";
    msg.alarmLevel = "Quá lạnh khẩn cấp - CRITICAL - LL";
    msg.alarmSeverity = "CRITICAL";
    msg.thresholdValue = ll;
    msg.alarmNote = "Thực tế: " + msg.currentTemp + "°C <= Ngưỡng LL: " + ll + "°C (L: " + l + "°C | H: " + h + "°C | HH: " + hh + "°C)";
} else if (t >= hh) {
    msg.alarmCode = "HH";
    msg.alarmLevel = "Quá nóng khẩn cấp - CRITICAL - HH";
    msg.alarmSeverity = "CRITICAL";
    msg.thresholdValue = hh;
    msg.alarmNote = "Thực tế: " + msg.currentTemp + "°C >= Ngưỡng HH: " + hh + "°C (LL: " + ll + "°C | L: " + l + "°C | H: " + h + "°C)";
} else if (t <= l) {
    msg.alarmCode = "L";
    msg.alarmLevel = "Cảnh báo lạnh - WARNING - L";
    msg.alarmSeverity = "WARNING";
    msg.thresholdValue = l;
    msg.alarmNote = "Thực tế: " + msg.currentTemp + "°C <= Ngưỡng L: " + l + "°C (LL: " + ll + "°C | H: " + h + "°C | HH: " + hh + "°C)";
} else if (t >= h) {
    msg.alarmCode = "H";
    msg.alarmLevel = "Cảnh báo nóng - WARNING - H";
    msg.alarmSeverity = "WARNING";
    msg.thresholdValue = h;
    msg.alarmNote = "Thực tế: " + msg.currentTemp + "°C >= Ngưỡng H: " + h + "°C (LL: " + ll + "°C | L: " + l + "°C | HH: " + hh + "°C)";
} else {
    msg.alarmCode = "OK";
    msg.alarmLevel = null;
    msg.alarmSeverity = null;
    msg.alarmNote = "Bình thường: " + msg.currentTemp + "°C";
}

return {msg: msg, metadata: metadata, msgType: msgType};

