configuration.jsScript:
if (msg.temperature == null) {
    return [];
}
if (msg.alarmCode == "HH") {
    return ['Create_HH', 'Clear_H', 'Clear_L', 'Clear_LL'];
} else if (msg.alarmCode == "H") {
    return ['Create_H', 'Clear_HH', 'Clear_L', 'Clear_LL'];
} else if (msg.alarmCode == "LL") {
    return ['Create_LL', 'Clear_L', 'Clear_H', 'Clear_HH'];
} else if (msg.alarmCode == "L") {
    return ['Create_L', 'Clear_LL', 'Clear_H', 'Clear_HH'];
} else {
    return ['Clear_HH', 'Clear_H', 'Clear_L', 'Clear_LL'];
}

