configuration.alarmDetailsBuildJs:
var details = {};
if (metadata.prevAlarmDetails != null) {
    details = JSON.parse(metadata.prevAlarmDetails);
}
details.code = msg.alarmCode;
details.level = msg.alarmLevel;
details.temperature = msg.currentTemp;
details.threshold = msg.thresholdValue;
details.LL = msg.alarm_LL;
details.L = msg.alarm_L;
details.H = msg.alarm_H;
details.HH = msg.alarm_HH;
details.note = msg.alarmNote;
return details;

